import{_ as o,o as a,c as i,ah as n}from"./chunks/framework.Dpoi9ndL.js";const e="/projects/uHandPi/en/latest/assets/image1.BWWdt93p.png",r="/projects/uHandPi/en/latest/assets/image2.BF1KwvoZ.png",s="/projects/uHandPi/en/latest/assets/image3.1.Db5j7GRu.png",d="/projects/uHandPi/en/latest/assets/image3.2.DjjXGyLa.png",c="/projects/uHandPi/en/latest/assets/image4.rYsSaU_W.png",l="/projects/uHandPi/en/latest/assets/image5.2yKmWVhP.png",p="/projects/uHandPi/en/latest/assets/image2.S3_8oM0E.png",h="/projects/uHandPi/en/latest/assets/image5.BNC4v04e.png",g="/projects/uHandPi/en/latest/assets/image7.BTAns1mF.png",u="/projects/uHandPi/en/latest/assets/image10.CTJPThZU.jpeg",x=JSON.parse('{"title":"1. Getting Ready","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1.getting_ready.md","filePath":"docs/1.getting_ready.md"}'),m={name:"docs/1.getting_ready.md"};function y(b,t,w,f,_,P){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="_1-getting-ready" tabindex="-1">1. Getting Ready <a class="header-anchor" href="#_1-getting-ready" aria-label="Permalink to &quot;1. Getting Ready&quot;">​</a></h1><h2 id="_1-1-uhandpi-introduction" tabindex="-1">1.1 uHandPi Introduction <a class="header-anchor" href="#_1-1-uhandpi-introduction" aria-label="Permalink to &quot;1.1 uHandPi Introduction&quot;">​</a></h2><p><strong>1.1.1 Introduction</strong></p><p>Powered by Raspberry Pi 5, uHandPi is an intelligent vision mechanical hand of 6 DOF. Adopting micro anti-blocking servo, its knuckles have 5 DOF, long service life, great flexibility. Pan-tilt adopts high accuracy digital servo and it can rotate 180 degree horizontally.</p><p>Loaded with HD camera, uHandPi can work with OpenCV to realize AI image recognition, image transmission, finger-guessing, etc.</p><img loading="lazy" height="539" width="314" class="common_img" src="'+e+'"><p><strong>1.1.2 Usage Precautions</strong></p><p>Please pay attention to the following points when using and storing this product:</p><p>(1) This product contains conductive components. Avoid contact with metal objects when powered on.</p><p>(2) After the robot is powered on, do not forcibly move the servo, as this may cause damage.</p><p>(3) If the robot runs for an extended period, the servos may become hot. Allow the robot to &quot;<strong>rest</strong>&quot; and wait for the servos to cool before resuming operation.</p><p>(4) Keep your face, glasses, and other body parts away from the robot while it is operating. Do not place fingers within the joint movement range to prevent injury. Also, be cautious of falls from high edges.</p><p>(5) The robot&#39;s servos are precision components and consumable parts. They may need replacement after long-term or intensive use.</p><p>(6) If the product will not be used for an extended period, fully charge the battery, remove it, and store it in a cool, dry place.</p><p><strong>1.1.3 Copyright Notice</strong></p><p>This manual is the property of Shenzhen Hiwonder Technology Co., Ltd. No organization or individual is permitted to reproduce, copy, translate, or distribute any content from this manual without authorization. Any unauthorized use or infringement of this manual&#39;s copyright will be subject to legal action by our company.</p><p>1.1.4 Disclaimer</p><p>The product described in this manual (including hardware, software, etc.) is provided &quot;<strong>as is</strong>&quot;. Every effort has been made to ensure the accuracy of this manual, but we cannot guarantee it is completely free from errors or omissions. This document is regularly reviewed, and we welcome feedback for improvements. Product features and specifications may change with version upgrades. For the latest product information, please contact customer service when placing your order. Furthermore, unless explicitly stated by Hiwonder, we are not responsible for any losses resulting from product malfunctions or damage under extreme conditions outside of typical use cases.</p><h2 id="_1-2-packing-list" tabindex="-1">1.2 Packing list <a class="header-anchor" href="#_1-2-packing-list" aria-label="Permalink to &quot;1.2 Packing list&quot;">​</a></h2><table border="1" class="docutils" style="text-align:center;"><thead><tr><th>No.</th><th><strong>Components</strong></th><th><strong>Quantity</strong></th><th><strong>Picture</strong></th></tr></thead><tbody><tr><td>1</td><td>uHandPi robot hand</td><td>1</td><td><img loading="lazy" height="539" width="314" src="'+e+'" style="width:200px;"></td></tr><tr><td>2</td><td>7.5V 6A power adapter</td><td>1</td><td><img loading="lazy" height="357" width="570" src="'+r+'" style="width:180px;"></td></tr><tr><td>3</td><td>Balls</td><td>2</td><td><img loading="lazy" height="316" width="316" src="'+s+'" style="width:60px;"><img loading="lazy" height="316" width="316" src="'+d+'" style="width:60px;"></td></tr><tr><td>4</td><td>Card reader</td><td>1</td><td><img loading="lazy" height="341" width="169" src="'+c+'" style="width:50px;"></td></tr><tr><td>5</td><td>Screwdriver</td><td>1</td><td><img loading="lazy" height="64" width="546" src="'+l+'" style="width:150px;"></td></tr></tbody></table><h2 id="_1-3-start-uhandpi" tabindex="-1">1.3 Start uHandPi <a class="header-anchor" href="#_1-3-start-uhandpi" aria-label="Permalink to &quot;1.3 Start uHandPi&quot;">​</a></h2><p><strong>1.3.1 Servo Wiring</strong></p><p>Connect the servo wires labeled ID1-ID5 respectively to the Raspberry Pi expansion board&#39;s 1, 2, 3, 4, 5, 6 interfaces. Note: connect the yellow/white wire to S, the red wire to +, and the gray/black wire to -.</p><img loading="lazy" height="820" width="1108" class="common_img" style="width:70%;" src="'+p+'" alt="2cac4b4329d633b6337209cbf5ec3930"><p><strong>1.3.2 Pulg in and Boot up</strong></p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>This section is for standardizing operational procedures. DC power cable has been connected to Raspberry Pi expansion board already before delivery.</p></section><p>(1) Connect red part of the DC power cable to + pole on Raspberry Pi expansion board, and black part to - pole.</p><img loading="lazy" height="515" width="697" class="common_img" style="width:70%;" src="'+h+'" alt="fac8f33419c35159c8baed9913d60025"><p>(2) Connect the male interface of the power adaptor to the female interface of the DC power cable. After that, plug in the power adaptor.</p><img loading="lazy" height="350" width="570" class="common_img" src="'+g+'" alt="4"><p>(3) Push the switch on Raspberry Pi expansion board to &quot;<strong>ON</strong>&quot;. At this time, LED1 and LED2 on Raspberry Pi will light up continuously. After a while, LED1 will flash every 2s, and the mechanical hand will in the posture shown below, which means that it boots up successfully. The Raspberry Pi is also a computer, and it takes a short while to boot up, approximately 30 seconds. Please be patient.</p><p>(4) After booting up the device successfully, the default mode is AP directly connection mode. And create a hotspot starting with HW.</p><img loading="lazy" height="348" width="723" class="common_img" style="width:50%;" src="'+u+'" alt="IMG_E0486"><p>(4) Next, you can go to &quot;<a href="https://docs.hiwonder.com/projects/uHandPi/en/latest/docs/2.quick_user_experience.html#app-installation-and-connection" target="_blank" rel="noreferrer"><strong>Quick User Experience\\2.1 APP Installation and Connection</strong></a>&quot; to learn the subsequent contents.</p>',34)])])}const k=o(m,[["render",y]]);export{x as __pageData,k as default};
